   163	    /// <summary>
   164	    /// Seals the guardian's background output capability once the job's
   165	    /// terminal is observed. The worker holds the bytes and has no channel to
   166	    /// the guardian's output events, so this host fetches the job's output over
   167	    /// the worker request protocol and seals the capture it retained at start.
   168	    /// Without this the capability is registered and never written, the
   169	    /// guardian's <c>TryGetJobRecovery</c> stays empty, and every background job
   170	    /// reports <c>recovery=unavailable</c> for the rest of its life.
   171	    /// </summary>
   172	    private void SealBackgroundJobOutput(
   173	        long publicJobId,
   174	        BackgroundJobCapture capture)
   175	    {
   176	        // The terminal callback runs under the worker event bridge's lock and
   177	        // this runtime's, so the worker round-trip cannot happen inline. The
   178	        // guardian owns the capability's own expiry, so a seal that loses its
   179	        // race is terminalized there rather than needing a result here.
   180	        _ = SealCoreAsync();
   181	
   182	        async Task SealCoreAsync()
   183	        {
   184	            try
   185	            {
   186	                var response = await capture.Slot.Process.ExecuteAsync(
   187	                        WorkerSessionOperationCodec.JobOutputOperation,
   188	                        new WorkerJobOutputArguments(publicJobId, 0),
   189	                        DateTimeOffset.FromUnixTimeMilliseconds(
   190	                            capture.DeadlineUnixTimeMilliseconds),
   191	                        CancellationToken.None)
   192	                    .ConfigureAwait(false);
   193	                var parsed = ParseTextResponse(
   194	                    response,
   195	                    WorkerSessionOperationCodec.JobOutputOperation);
   196	                // A failed fetch leaves the capability unsealed on purpose. The
   197	                // guardian then reports the artifact unavailable, which is true;
   198	                // sealing an empty artifact would advertise a handle to content
   199	                // this host never read.
   200	                if (parsed.Text is not { } text) return;
   201	                _ = await capture.Capture.SealAsync(
   202	                        new OutputArtifactContent(
   203	                            text,
   204	                            [],
   205	                            [],
   206	                            [],
   207	                            ExitCode: null,
   208	                            OutputProvenance.DirectText),
   209	                        JobOutputSealGrace)
   210	                    .ConfigureAwait(false);
   211	            }
   212	            catch (Exception exception) when (!IsFatal(exception))
   213	            {
   214	                // Same truthfulness rule as a failed fetch: an unsealed
   215	                // capability is honest, an invented artifact is not.
   216	            }
   217	            finally
   218	            {
   219	                capture.Dispose();
   220	            }
   221	        }
   222	    }
