   659	    private async ValueTask<PrivateHostOperationOutcome>
   660	        ExecuteBackgroundAsync(
   661	            OperationRequest request,
   662	            AliasRuntime alias,
   663	            PrivateHostWorkerSlot slot,
   664	            CancellationToken cancellationToken)
   665	    {
   666	        var operation = (InvokeBackgroundOperation)request.Operation;
   667	        var deadline = request.DeadlineUnixTimeMilliseconds!.Value;
   668	        IExecutionOutputCaptureOwner? captureOwner;
   669	        try
   670	        {
   671	            captureOwner = _output.CreateExecutionCapture(request) ??
   672	                throw new InvalidOperationException(
   673	                    "Private host output transfer returned no capture owner.");
   674	        }
   675	        catch (Exception exception) when (!IsFatal(exception))
   676	        {
   677	            return await RefuseAsync(
   678	                    request,
   679	                    GuardianHostPrivateDetailCode.OutputCapabilityInvalid,
   680	                    cancellationToken)
   681	                .ConfigureAwait(false);
   682	        }
   683	
   684	        CapabilityToken capability;
   685	        try
   686	        {
   687	            // Preparing against the request deadline is preparing against the
   688	            // output capability's own expiry: the guardian mints both from the
   689	            // same admitted deadline. An unavailable preparation is not a
   690	            // dispatch failure - the job still runs and the guardian reports the
   691	            // artifact unavailable, exactly as it did before any capture existed.
   692	            var preparation = await captureOwner.PrepareAsync(
   693	                    DateTimeOffset.FromUnixTimeMilliseconds(deadline),
   694	                    JobOutputSealGrace,
   695	                    cancellationToken)
   696	                .ConfigureAwait(false);
   697	            if (!preparation.Available)
   698	            {
   699	                captureOwner.Dispose();
   700	                captureOwner = null;
   701	            }
   702	
   703	            lock (_gate)
   704	            {
   705	                if (_aliases.Values.Sum(value => value.OutstandingJobs.Count) >=
   706	                    ContractLimits.MaximumOutstandingPrivateRequests)
   707	                {
   708	                    return PrivateHostOperationOutcome.Failed(
   709	                        GuardianHostPrivateDetailCode.SessionBusy);
   710	                }
   711	                capability = _createJobCapability() ??
   712	                    throw new InvalidOperationException(
   713	                        "Private host job capability source returned no capability.");
   714	                // Reserve before the commit write so a fast job's terminal can
   715	                // never precede the capability's registration. The output
   716	                // capture is registered in the same breath and for the same
   717	                // reason: the terminal is what seals it, so it has to be
   718	                // findable before the job can produce one.
   719	                if (!alias.OutstandingJobs.TryAdd(
   720	                        operation.PublicJobId.Value,
   721	                        capability))
   722	                {
   723	                    throw new InvalidOperationException(
   724	                        "Guardian-reserved background job ID was reused.");
   725	                }
   726	                if (captureOwner is not null)
   727	                {
   728	                    alias.JobCaptures[operation.PublicJobId.Value] =
   729	                        new BackgroundJobCapture(captureOwner, slot, deadline);
   730	                    captureOwner = null;
   731	                }
   732	            }
   733	        }
   734	        finally
   735	        {
   736	            captureOwner?.Dispose();
   737	        }
   738	
   739	        try
   740	        {
   741	            var start = await _prepared.ExecuteBackgroundAsync(
   742	                    request,
   743	                    slot,
   744	                    cancellationToken)
   745	                .ConfigureAwait(false);
   746	            if (!start.Started)
   747	            {
   748	                ReleaseUnstartedBackgroundJob(alias, operation.PublicJobId.Value);
   749	                return PrivateHostOperationOutcome.Failed(
   750	                    GuardianHostPrivateDetailCode.OperationNotDispatched);
   751	            }
   752	        }
   753	        catch
   754	        {
   755	            ReleaseUnstartedBackgroundJob(alias, operation.PublicJobId.Value);
   756	            throw;
   757	        }
   758	        return PrivateHostOperationOutcome.Completed(
   759	            new InvokeBackgroundResult(operation.PublicJobId, capability));
   760	    }
